import numpy as np
import json
import base64
import zlib

# 1. Official Tournament Imports
from pkbot.actions import ActionFold, ActionCall, ActionCheck, ActionRaise, ActionBid
from pkbot.states import GameInfo, PokerState, STARTING_STACK
from pkbot.base import BaseBot
from pkbot.runner import parse_args, run_bot

# ==========================================
# PASTE YOUR NEW 'TOURNAMENT_PAYLOAD' HERE
# ==========================================
BRAIN_PAYLOAD = ""

# ==========================================
# CONSTANTS & VECTORIZER
# ==========================================
ACTIONS = 4  
STATE_DIM = 165

DECK_STRINGS = [r+s for r in '23456789TJQKA' for s in 'shdc']
DECK_MAP = {card: i for i, card in enumerate(DECK_STRINGS)}

# ==========================================
# PURE NUMPY INFERENCE ENGINE (NO PYTORCH)
# ==========================================
class NumpyPokerNet:
    def __init__(self, payload_string):
        if payload_string == "PASTE_YOUR_NEW_BASE64_STRING_HERE":
            print("WARNING: No payload found! Bot will crash.")
            return
            
        compressed_bytes = base64.b64decode(payload_string)
        json_text = zlib.decompress(compressed_bytes).decode('utf-8')
        weights = json.loads(json_text)
        
        self.W1 = np.array(weights['fc1.weight'], dtype=np.float32)
        self.b1 = np.array(weights['fc1.bias'], dtype=np.float32)
        
        self.W2 = np.array(weights['fc2.weight'], dtype=np.float32)
        self.b2 = np.array(weights['fc2.bias'], dtype=np.float32)
        
        self.W3 = np.array(weights['fc3.weight'], dtype=np.float32)
        self.b3 = np.array(weights['fc3.bias'], dtype=np.float32)
        
        self.W4 = np.array(weights['fc4.weight'], dtype=np.float32)
        self.b4 = np.array(weights['fc4.bias'], dtype=np.float32)

    def relu(self, x):
        return np.maximum(0.0, x)

    def forward(self, x):
        x = self.relu(np.dot(x, self.W1.T) + self.b1)
        x = self.relu(np.dot(x, self.W2.T) + self.b2)
        x = self.relu(np.dot(x, self.W3.T) + self.b3)
        return np.dot(x, self.W4.T) + self.b4

# ==========================================
# THE TOURNAMENT BOT
# ==========================================
class PokerastinotBot(BaseBot):
    def __init__(self):
        super().__init__()
        self.model = NumpyPokerNet(BRAIN_PAYLOAD)

    def vectorize_state(self, state: PokerState):
        pot_ratio = min(1.0, state.pot / 20000.0) 
        stack_ratio = min(1.0, state.my_chips / 10000.0)
        cost_ratio = min(1.0, state.cost_to_call / max(1, state.pot))
        
        # Determine Street safely
        street_name = state.street.lower()
        street_map = {'pre-flop': 0.0, 'flop': 0.5, 'turn': 0.75, 'river': 1.0}
        street_val = street_map.get(street_name, 0.0)
        
        # [FIX 1] THE HIDDEN AUCTION GHOSTING OVERRIDE
        if ActionBid in state.legal_actions:
            street_val = 0.25
            
        button_val = 0.0 if state.is_bb else 1.0 

        hole_vec = np.zeros(52); board_vec = np.zeros(52); revealed_vec = np.zeros(52)
        for c in state.my_hand: hole_vec[DECK_MAP[str(c)]] = 1.0
        for c in state.board: board_vec[DECK_MAP[str(c)]] = 1.0
            
        opp_revealed = getattr(state, 'opp_revealed_cards', [])
        
        auc_status = np.zeros(4)
        if street_val <= 0.25 and len(opp_revealed) == 0:
            auc_status[0] = 1.0 
        elif len(opp_revealed) > 0:
            auc_status[1] = 1.0 
            for c in opp_revealed: revealed_vec[DECK_MAP[str(c)]] = 1.0
        else:
            auc_status[2] = 1.0 

        vec = np.concatenate([
            [pot_ratio, stack_ratio, cost_ratio, street_val, button_val],
            auc_status, hole_vec, board_vec, revealed_vec
        ])
        return vec.astype(np.float32)

    def on_hand_start(self, game_info: GameInfo, current_state: PokerState) -> None:
        pass

    def on_hand_end(self, game_info: GameInfo, current_state: PokerState) -> None:
        pass

    def get_move(self, game_info: GameInfo, state: PokerState):
        valid_actions = state.legal_actions
        
        state_arr = self.vectorize_state(state)
        regrets = self.model.forward(state_arr)
            
        pos_regrets = np.maximum(regrets, 0.0)
        sum_regrets = np.sum(pos_regrets)
        strategy = pos_regrets / sum_regrets if sum_regrets > 0 else np.ones(ACTIONS) / ACTIONS
            
        action_idx = np.random.choice(ACTIONS, p=strategy)

        if ActionBid in valid_actions:
            # The MC Bot averages a bid of 10.01. 
            # We bid 12 to guarantee the win, but only pay their ~10 via second-price rules.
            override_bid = 9
            
            # Safety check: don't bet more than we physically have
            max_bid = int(state.my_chips)
            final_bid = max(0, min(override_bid, max_bid))
            return ActionBid(final_bid) 
            
        if action_idx == 0:
            return ActionCheck() if ActionCheck in valid_actions else ActionFold() 
            
        if action_idx == 1:
            if ActionCall in valid_actions: return ActionCall() 
            return ActionCheck() if ActionCheck in valid_actions else ActionFold() 
            
        # [FIX 2] THE RAISE BOUNDS CRASH OVERRIDE
        if ActionRaise in valid_actions: 
            # Step A: Default to the literal rulebook definition
            min_r = getattr(state, 'min_raise', 20)
            max_r = getattr(state, 'max_raise', int(min(state.my_chips, getattr(state, 'opp_chips', state.my_chips))))
            
            # Step B: If the engine explicitly provides a tuple, trust the engine
            if hasattr(state, 'raise_bounds') and state.raise_bounds is not None:
                min_r, max_r = state.raise_bounds

            target = int(state.pot * 0.56) if action_idx == 2 else int(state.pot * 1.03)
            
            # Step C: Mathematically lock the target bet inside the legal bounds
            final_raise = max(min_r, min(target, max_r))
            return ActionRaise(int(final_raise)) 
            
        if ActionCall in valid_actions: return ActionCall() 
        return ActionCheck() if ActionCheck in valid_actions else ActionFold() 

if __name__ == '__main__':
    bot = PokerastinotBot()
    run_bot(bot, parse_args())